package software.amazon.event.ruler;

/**
 * The types of value matches that Ruler supports
 */
public enum MatchType {

    // exact string
    EXACT,
    // absent key pattern
    ABSENT,
    // existence pattern
    EXISTS,
    // string prefix
    PREFIX,
    // case-insensitive string prefix
    PREFIX_EQUALS_IGNORE_CASE,
    // string suffix
    SUFFIX,
    // case-insensitive string suffix
    SUFFIX_EQUALS_IGNORE_CASE,
    // exact numeric match
    NUMERIC_EQ,
    // numeric range with high & low bound & </<=/>/>= options
    NUMERIC_RANGE,
    // deny list effect
    ANYTHING_BUT,
    // deny list effect (case insensitive)
    ANYTHING_BUT_IGNORE_CASE,
    // anything that doesn't start with this
    ANYTHING_BUT_PREFIX,
    // anything that doesn't end with this
    ANYTHING_BUT_SUFFIX,
    // anything that doesn't match the wildcard pattern
    ANYTHING_BUT_WILDCARD,
    // case-insensitive string match
    EQUALS_IGNORE_CASE,
    // string match using one or more non-consecutive '*' wildcard characters
    WILDCARD
}

